-- ============================================================
-- ZmartCredential — restore the built-in reference data
--
-- Use this after the tables were emptied (TRUNCATE). It puts back only what the
-- application needs to work: plans, permissions, payers, payer forms, document
-- types, email templates, pricing and privileging lists, plus Flyway's history so
-- the backend still starts. It does NOT add demo clients, providers or users.
--
-- Safe to run more than once: every row uses INSERT IGNORE, so rows that are
-- already there are left unchanged.
--
-- Run:  mysql -u admin -p credentialing < restore_reference_data.sql
-- then restart the backend (pm2 restart zmartcredential-backend).
-- ============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

