-- payer
INSERT  IGNORE INTO `payer` (`id`, `code`, `name`, `full_name`, `category`, `payer_type`, `color`, `app_form`, `integration`, `api_support`, `submission_method`, `api_available`, `api_vendor`, `api_docs_url`, `submission_notes`, `caqh_participating`, `portal_url`, `avg_tat_days`, `pricing_category`, `pricing_mult`, `recred_cycle_months`, `sort_order`, `active`, `created_at`, `updated_at`) VALUES (1,'bcbs_tx','BCBS TX','Blue Cross Blue Shield of Texas','Commercial','PPO/HMO','#1d4ed8','Ambetter Provider Set-up Form','caqh','partial','caqh_roster',0,'Availity (claims only)',NULL,'Blue Cross Blue Shield of Texas (HCSC subsidiary). Pulls provider data from CAQH ProView. Enrollment via Availity Essentials or BCBSTX portal. No direct enrollment API.',1,'https://providers.bcbstx.com',49,'commercial',1.05,24,1,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(2,'aetna','Aetna','Aetna (CVS Health)','Commercial','PPO/HMO','#7c2d12','CAQH + Aetna Provider Portal','caqh','partial','caqh_roster',0,'Availity + NaviNet',NULL,'CVS Health subsidiary. Uses CAQH ProView + Availity. Aetna Provider Portal for direct submissions. No public enrollment API.',1,'https://www.aetna.com/health-care-professionals.html',52,'commercial',1.00,24,3,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(3,'cigna','Cigna','Cigna Healthcare','Commercial','PPO/HMO','#065f46','CAQH + CignaForHCP','caqh','portal','caqh_roster',0,'CignaForHCP (portal)',NULL,'Enrollment via CignaForHCP portal + CAQH. API program exists for claims and eligibility only.',1,'https://cignaforhcp.cigna.com',61,'commercial',1.02,24,4,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(4,'uhc','UHC','UnitedHealthcare (UHG)','Commercial','PPO/HMO','#1e3a8a','CAQH + UHC Provider Portal','caqh','full','caqh_roster',1,'UHC/Optum APIs','https://developer.uhc.com','UHC/Optum has public developer APIs at developer.uhc.com — Provider Directory, Operations. Enrollment still goes through CAQH roster + UHC Provider Portal.',1,'https://uhcprovider.com',58,'commercial',1.08,24,5,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(5,'humana','Humana','Humana','Commercial','PPO/HMO','#15803d','CAQH + Availity','availity','portal','availity',1,'Availity + Humana Developer','https://developers.humana.com','Humana developer portal has FHIR-based APIs for benefits, claims, and member data. Enrollment still goes through CAQH roster + Availity.',1,'https://provider.humana.com',64,'commercial',0.98,24,6,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(6,'medicare','Medicare','Medicare (CMS)','Federal','FFS','#1e40af','CMS-855I (Individual) / CMS-855B (Group) / CMS-855O (Order)','pecos','portal','pecos',0,'PECOS','https://data.cms.gov/provider-data/','PECOS is CMS\'s official enrollment system — web portal only, no public enrollment API. Blue Button 2.0 FHIR API exists for claims data. ~$688 application fee.',0,'https://pecos.cms.hhs.gov',60,'medicare',1.00,24,15,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(7,'medicaid','Medicaid TX','Texas Medicaid (TMHP)','State Medicaid','FFS','#0f766e','TMHP Provider Enrollment','portal','portal','state_portal',0,'TMHP (state-specific)',NULL,'Texas Medicaid Healthcare Partnership. Required for Texas Medicaid participation. Portal-based enrollment with state-specific requirements.',0,'https://www.tmhp.com',92,'medicaid',1.00,24,17,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(8,'superior','Superior','Superior HealthPlan (TX MCO)','Medicaid MCO','Managed','#0369a1','MCO App via Availity','availity','portal','availity',1,'Availity (Centene subsidiary)','https://apigw.availity.com','Centene subsidiary covering Texas STAR, STAR+PLUS, CHIP. Uses Availity for enrollment and claims.',1,'https://www.superiorhealthplan.com/providers.html',75,'medicaid',0.95,24,12,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(9,'anthem','Anthem','Anthem (Elevance Health) BCBS','Commercial','PPO/HMO','#003DA5','CAQH + Availity','availity','partial','availity',1,'Availity','https://apigw.availity.com','Anthem is now \'Elevance Health\'. 14 BCBS state plans. Primary channel is Availity Essentials + API Gateway for X12 and REST.',1,'https://availity.com',55,NULL,1.00,24,7,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(10,'kaiser','Kaiser','Kaiser Permanente','Commercial (HMO)','HMO','#006BA6','Kaiser Provider Enrollment (internal)','portal','portal','portal_only',0,'Kaiser Provider Portal',NULL,'Closed network — Kaiser mostly employs physicians directly. External credentialing is limited; contact regional Kaiser office for details.',0,'https://providers.kaiserpermanente.org',90,NULL,1.00,24,8,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(11,'molina','Molina','Molina Healthcare','Medicaid MCO','Managed','#0072BC','Molina Provider Application','availity','portal','availity',1,'Availity','https://apigw.availity.com','Multi-state Medicaid MCO. Uses Availity for most electronic transactions. Portal-based enrollment with roster support via CAQH.',1,'https://provider.molinahealthcare.com',72,NULL,1.00,24,9,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(12,'centene','Centene','Centene / Ambetter / WellCare','Medicaid MCO','Managed','#009999','Centene Provider Enrollment','availity','portal','availity',1,'Availity','https://apigw.availity.com','Centene operates Ambetter (marketplace), Fidelis NY, Superior TX, Peach State GA, WellCare, and others. Availity is primary channel for enrollment and operations.',1,'https://provider.ambetter.centene.com',68,NULL,1.00,24,10,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(13,'wellcare','WellCare','WellCare (Centene)','Medicare Advantage','Medicare Advantage','#005A9C','WellCare Provider Enrollment','availity','portal','availity',1,'Availity','https://apigw.availity.com','WellCare is a Centene subsidiary focused on Medicare Advantage and Medicaid. Enrollment via Availity.',1,'https://wellcare.com/provider',70,NULL,1.00,24,11,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(14,'bcbs_il','BCBS IL','Blue Cross Blue Shield of Illinois','Commercial','PPO/HMO','#1d4ed8','BCBSIL Provider Enrollment','caqh','partial','caqh_roster',0,'Availity',NULL,'Also an HCSC plan. CAQH roster + Availity for enrollment. Common BCBS plan nationwide.',1,'https://providers.bcbsil.com',51,'commercial',1.00,24,2,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(15,'magellan','Magellan','Magellan Health','Behavioral Health','Managed','#4a148c','Magellan Provider Enrollment','portal','portal','portal_only',0,'Magellan Provider Portal',NULL,'Behavioral health benefits manager (BHO). Portal-based enrollment + CAQH data. Used by many commercial payers for behavioral health carve-outs.',1,'https://www.magellanprovider.com',80,'commercial',1.00,24,13,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(16,'carelon','Carelon','Carelon Behavioral Health (Elevance)','Behavioral Health','Managed','#5e35b1','Carelon Provider Enrollment','availity','portal','availity',0,'Availity + Carelon Portal',NULL,'Formerly Beacon Health Options, now part of Elevance Health. Behavioral health carve-out for many commercial plans.',1,'https://providers.carelon.com',75,'commercial',1.00,24,14,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(17,'medicare_adv','Medicare Advantage','Medicare Advantage (Various)','Medicare Advantage','Managed','#1e3a8a','Varies by MA plan','caqh','portal','caqh_roster',0,'Varies (UHC, Humana, Aetna, Anthem, etc.)',NULL,'Medicare Advantage plans are offered by private payers. Each MA plan (UHC MA, Humana MA, Aetna MA, Kaiser MA) has its own process — usually CAQH + their portal.',1,NULL,65,'medicare',1.00,24,16,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(18,'medicaid_ca','Medi-Cal CA','California Medicaid (PAVE)','State Medicaid','FFS','#0f766e','DHCS PAVE Application','portal','portal','state_portal',0,'DHCS PAVE',NULL,'California Medi-Cal uses PAVE (Provider Application and Validation for Enrollment). FHIR-based API in development as of 2024-2025.',0,'https://www.dhcs.ca.gov/provgovpart',110,'medicaid',1.00,24,18,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(19,'medicaid_ny','Medicaid NY','New York Medicaid (eMedNY)','State Medicaid','FFS','#0f766e','eMedNY Enrollment Application','portal','portal','state_portal',0,'eMedNY (CSC State Health)',NULL,'New York State Medicaid enrollment through eMedNY. Portal-based with required training completion.',0,'https://www.emedny.org',100,'medicaid',1.00,24,19,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(20,'tricare','TRICARE','TRICARE (Military)','Federal','Managed','#4a5568','TRICARE Provider Enrollment via Humana (East) or Health Net (West)','portal','portal','portal_only',0,'Humana Military (East) + Health Net Federal (West)',NULL,'US military health benefits. East region administered by Humana Military, West region by Health Net Federal Services. Use their portals + CAQH data.',1,'https://www.tricare.mil/providers',55,'commercial',1.00,24,20,1,'2026-10-07 15:12:10','2026-10-07 15:12:10'),(21,'va_ccn','VA CCN','VA Community Care Network','Federal','Managed','#1b5e20','VA CCN Provider Application (via Optum or TriWest)','portal','portal','portal_only',0,'Optum (Regions 1-3) + TriWest (Regions 4-5)',NULL,'VA Community Care Network for serving veterans. Administered by Optum in regions 1-3 and TriWest in regions 4-5.',1,'https://www.va.gov/COMMUNITYCARE',85,'commercial',1.00,24,21,1,'2026-10-07 15:12:10','2026-10-07 15:12:10');

