-- email_template
INSERT  IGNORE INTO `email_template` (`id`, `org_id`, `type`, `name`, `subject`, `body`) VALUES (1,NULL,'missing_docs','Missing Documents Reminder','{{provider_first_name}}, you have {{pending_document_count}} documents needed to complete your credentialing','Hi {{provider_first_name}},\n\nYour credentialing file is currently incomplete. There are {{pending_document_count}} required document(s) that we still need.\n\nMissing documents may delay your credentialing or affect your network status.\n\nThe following documents are still needed:\n{{missing_document_list}}\n\nSecure Access PIN: {{pin}}\n\nUpload your documents: {{upload_link}}\n\nLink expires: {{link_expires}}\n\nIf the link has expired by the time you access it, please contact {{organization_name}} and we will send you a new one.'),(2,NULL,'expiring','Expiring Documents Reminder','{{provider_first_name}}, some of your credentialing documents are expiring soon','Hi {{provider_first_name}},\n\nThe following documents on file are expiring soon:\n{{expiring_document_list}}\n\nPlease upload renewed copies: {{upload_link}}\n\nThank you,\n{{organization_name}}'),(3,NULL,'incomplete','Incomplete Profile Reminder','{{provider_first_name}}, please complete your provider profile','Hi {{provider_first_name}},\n\nYour provider profile is incomplete. Please sign in and complete the remaining fields so we can continue your credentialing.\n\n{{upload_link}}\n\nThank you,\n{{organization_name}}');

